import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

/**
 * Load this application's own `.env` file.
 *
 * Unlike Next.js, `tsx`/`node` do not read env files automatically, and nothing
 * loads the repository-root file into this process. `apps/worker/.env` is
 * generated by `scripts/sync-app-env.mjs` from the root development file.
 *
 * Variables already present in the real process environment take precedence, so
 * a deployed platform's configuration and the values injected by the E2E runner
 * are never overridden by the file.
 *
 * This module must be imported before `./env.js`, which validates configuration
 * at import time and exits the process when it is incomplete.
 */
function loadWorkerEnvFile() {
  const moduleDirectory = dirname(fileURLToPath(import.meta.url));
  const envPath = resolve(moduleDirectory, "../.env");

  try {
    process.loadEnvFile(envPath);
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== "ENOENT") {
      throw error;
    }
  }
}

loadWorkerEnvFile();
